css:
.exd-algo-wheel{--exd-aw-ln:#19212F;--exd-aw-dim:#6C7A92;--exd-aw-ac:#6EA8FF;--exd-aw-up:#35D07F;--exd-aw-wn:#F3B44A;--exd-aw-mono:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;box-sizing:border-box;width:100%;background:linear-gradient(180deg,#0E131C,#090C12);border:1px solid var(--exd-aw-ln);border-radius:8px;padding:8px 9px 7px;color:#E6EBF5;font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;font-size:10px;font-variant-numeric:tabular-nums}
.exd-algo-wheel *{box-sizing:border-box}
.exd-algo-wheel-hd{display:flex;align-items:center;gap:6px;font-size:8px;letter-spacing:.13em;color:var(--exd-aw-dim);padding-bottom:6px;border-bottom:1px solid var(--exd-aw-ln)}
.exd-algo-wheel-tag{font-weight:700;color:#95A4BC}
.exd-algo-wheel-ord{margin-left:auto;font-family:var(--exd-aw-mono);letter-spacing:.02em;color:#C9D4E6;font-size:9px}
.exd-algo-wheel-b{color:var(--exd-aw-up);margin-right:5px;font-weight:800}
.exd-algo-wheel-adv{font-family:var(--exd-aw-mono);color:var(--exd-aw-dim);font-size:9px}
.exd-algo-wheel-main{display:flex;gap:8px;align-items:center;padding:7px 0 5px}
.exd-algo-wheel-dial{position:relative;width:116px;height:116px;flex:none;outline:none;border-radius:50%}
.exd-algo-wheel-dial:focus-visible{box-shadow:0 0 0 2px rgba(110,168,255,.55)}
.exd-algo-wheel-svg{width:100%;height:100%;display:block}
.exd-algo-wheel-seg{cursor:pointer;transition:fill .16s ease}
.exd-algo-wheel-lb{font-family:var(--exd-aw-mono);font-size:8px;letter-spacing:.06em;fill:#7C8CA6;pointer-events:none}
.exd-algo-wheel-lb-on{fill:#0A0D13;font-weight:700}
.exd-algo-wheel-ctr{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;pointer-events:none;gap:1px}
.exd-algo-wheel-code{font-family:var(--exd-aw-mono);font-size:15px;font-weight:700;letter-spacing:.03em;color:#F2F6FF}
.exd-algo-wheel-sub{font-size:7.5px;letter-spacing:.1em;color:var(--exd-aw-dim);text-transform:uppercase}
.exd-algo-wheel-side{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}
.exd-algo-wheel-p{display:flex;justify-content:space-between;align-items:baseline;font-size:8px;letter-spacing:.1em;color:var(--exd-aw-dim);border-bottom:1px dotted rgba(108,122,146,.22);padding-bottom:2px}
.exd-algo-wheel-p b{font-family:var(--exd-aw-mono);font-size:10px;letter-spacing:0;color:#DCE4F2;font-weight:600}
.exd-algo-wheel-rng{-webkit-appearance:none;appearance:none;width:100%;height:12px;background:transparent;margin:0;outline:none;cursor:ew-resize}
.exd-algo-wheel-rng::-webkit-slider-runnable-track{height:3px;border-radius:2px;background:linear-gradient(90deg,rgba(110,168,255,.75),rgba(110,168,255,.16))}
.exd-algo-wheel-rng::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:9px;height:9px;margin-top:-3px;border-radius:2px;background:#6EA8FF;box-shadow:0 0 0 2px rgba(10,13,19,.9)}
.exd-algo-wheel-rng::-moz-range-track{height:3px;border-radius:2px;background:rgba(110,168,255,.28)}
.exd-algo-wheel-rng::-moz-range-thumb{width:9px;height:9px;border:none;border-radius:2px;background:#6EA8FF}
.exd-algo-wheel-rng:focus-visible::-webkit-slider-thumb{box-shadow:0 0 0 2px rgba(110,168,255,.5)}
.exd-algo-wheel-out{display:grid;grid-template-columns:1fr 1fr 1fr;gap:5px;padding:6px 0;border-top:1px solid var(--exd-aw-ln);border-bottom:1px solid var(--exd-aw-ln)}
.exd-algo-wheel-o{display:flex;flex-direction:column;gap:2px}
.exd-algo-wheel-o span{font-size:7.5px;letter-spacing:.11em;color:var(--exd-aw-dim)}
.exd-algo-wheel-o b{font-family:var(--exd-aw-mono);font-size:11px;font-weight:600;color:#F2F6FF}
.exd-algo-wheel-cost{color:var(--exd-aw-wn)}
.exd-algo-wheel-risk{color:#9FB2CC}
.exd-algo-wheel-arm{display:block;width:100%;margin:7px 0 6px;padding:5px 0;border:1px solid rgba(110,168,255,.42);border-radius:5px;background:rgba(110,168,255,.12);color:#BBD5FF;font-family:var(--exd-aw-mono);font-size:9px;letter-spacing:.16em;font-weight:700;cursor:pointer;transition:background .15s ease}
.exd-algo-wheel-arm:hover{background:rgba(110,168,255,.2)}
.exd-algo-wheel-arm:focus-visible{outline:none;box-shadow:0 0 0 2px rgba(110,168,255,.5)}
.exd-algo-wheel-on{border-color:rgba(53,208,127,.5);background:rgba(53,208,127,.14);color:#8FEFBE;animation:exd-algo-wheel-pulse 1.6s ease-in-out infinite}
.exd-algo-wheel-ft{display:flex;justify-content:space-between;font-size:7.5px;letter-spacing:.1em;color:#4E5A70}
@keyframes exd-algo-wheel-pulse{0%,100%{box-shadow:0 0 0 0 rgba(53,208,127,0)}50%{box-shadow:0 0 0 3px rgba(53,208,127,.14)}}
@media (prefers-reduced-motion: reduce){
.exd-algo-wheel-on{animation:none}
.exd-algo-wheel-seg{transition:none}
}

js:
var S=[{c:'VWAP',n:'schedule',k:1.00,p:12},
       {c:'TWAP',n:'time slice',k:1.06,p:10},
       {c:'POV',n:'participate',k:0.94,p:15},
       {c:'IS',n:'shortfall',k:0.88,p:20},
       {c:'DARK',n:'liquidity seek',k:0.72,p:8},
       {c:'CLOSE',n:'MOC ramp',k:1.18,p:6}];
var VOL=8100000,MINS=320,QTY=250000,SIG=148,T0=10*60+42;
var g=root.querySelector('.exd-algo-wheel-arcs');
var dial=root.querySelector('.exd-algo-wheel-dial');
var rng=root.querySelector('.exd-algo-wheel-rng');
var arm=root.querySelector('.exd-algo-wheel-arm');
var idx=0,pov=12,armed=false;
function pt(a,r){return [(60+r*Math.cos(a)).toFixed(2),(60+r*Math.sin(a)).toFixed(2)];}
function seg(i){
  var gap=0.05,st=-Math.PI/2+i*Math.PI/3+gap,en=-Math.PI/2+(i+1)*Math.PI/3-gap;
  var a=pt(st,53),b=pt(en,53),c=pt(en,34),d=pt(st,34);
  return 'M'+a[0]+' '+a[1]+'A53 53 0 0 1 '+b[0]+' '+b[1]+'L'+c[0]+' '+c[1]+'A34 34 0 0 0 '+d[0]+' '+d[1]+'Z';
}
function build(){
  var h='';
  for(var i=0;i<S.length;i++){
    var mid=-Math.PI/2+(i+0.5)*Math.PI/3,l=pt(mid,43.5);
    h+='<path class="exd-algo-wheel-seg" data-i="'+i+'" d="'+seg(i)+'"></path>';
    h+='<text class="exd-algo-wheel-lb" data-i="'+i+'" x="'+l[0]+'" y="'+l[1]+'" text-anchor="middle" dominant-baseline="middle">'+S[i].c+'</text>';
  }
  g.innerHTML=h;
  Array.prototype.forEach.call(g.querySelectorAll('.exd-algo-wheel-seg'),function(p){
    p.addEventListener('click',function(){idx=+p.getAttribute('data-i');pov=S[idx].p;rng.value=pov;paint();});
  });
}
function fmt(n,d){return n.toFixed(d);}
function paint(){
  Array.prototype.forEach.call(g.querySelectorAll('.exd-algo-wheel-seg'),function(p){
    var on=+p.getAttribute('data-i')===idx;
    p.setAttribute('fill',on?'rgba(110,168,255,.72)':'rgba(110,168,255,.09)');
    p.setAttribute('stroke',on?'rgba(150,196,255,.9)':'rgba(110,168,255,.22)');
    p.setAttribute('stroke-width','1');
  });
  Array.prototype.forEach.call(g.querySelectorAll('.exd-algo-wheel-lb'),function(t){
    t.setAttribute('class','exd-algo-wheel-lb'+(+t.getAttribute('data-i')===idx?' exd-algo-wheel-lb-on':''));
  });
  var s=S[idx];
  root.querySelector('.exd-algo-wheel-code').textContent=s.c;
  root.querySelector('.exd-algo-wheel-sub').textContent=s.n;
  root.querySelector('.exd-algo-wheel-pov').textContent=pov+'%';
  var rate=(pov/100)*(VOL/MINS);
  var dur=Math.min(MINS,QTY/rate);
  var imp=s.k*9.2*Math.pow(pov/12,0.6);
  var spr=1.15+pov*0.035;
  var risk=SIG*Math.sqrt(dur/390)/1.732;
  var end=T0+Math.round(dur);
  root.querySelector('.exd-algo-wheel-rate').textContent=Math.round(rate).toLocaleString('en-US')+'/m';
  root.querySelector('.exd-algo-wheel-eta').textContent=Math.floor(end/60)+':'+('0'+(end%60)).slice(-2);
  root.querySelector('.exd-algo-wheel-cost').textContent=fmt(imp+spr,1)+' bps';
  root.querySelector('.exd-algo-wheel-risk').textContent='±'+fmt(risk,1);
  root.querySelector('.exd-algo-wheel-dur').textContent=Math.round(dur)+'m';
  dial.setAttribute('aria-label','Execution strategy: '+s.c+' at '+pov+' percent participation');
}
function setArm(v){
  armed=v;
  arm.classList.toggle('exd-algo-wheel-on',v);
  arm.textContent=v?'ARMED · F9 TO SEND':'ARM & ROUTE';
}
rng.addEventListener('input',function(){pov=+rng.value;paint();});
arm.addEventListener('click',function(){setArm(!armed);});
dial.addEventListener('keydown',function(e){
  var k=e.key;
  if(k==='ArrowRight'){idx=(idx+1)%S.length;pov=S[idx].p;rng.value=pov;}
  else if(k==='ArrowLeft'){idx=(idx+S.length-1)%S.length;pov=S[idx].p;rng.value=pov;}
  else if(k==='ArrowUp'){pov=Math.min(30,pov+1);rng.value=pov;}
  else if(k==='ArrowDown'){pov=Math.max(3,pov-1);rng.value=pov;}
  else if(k==='Enter'||k===' '){setArm(!armed);e.preventDefault();return;}
  else return;
  e.preventDefault();paint();
});
build();paint();

css:
.exd-parent-child{--exd-pc-ln:#19212F;--exd-pc-dim:#6C7A92;--exd-pc-up:#35D07F;--exd-pc-dn:#FF5F6D;--exd-pc-wn:#F3B44A;--exd-pc-mono:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;box-sizing:border-box;width:100%;background:linear-gradient(180deg,#0E131C,#090C12);border:1px solid var(--exd-pc-ln);border-radius:8px;padding:8px 9px 7px;color:#E6EBF5;font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;font-size:10px;font-variant-numeric:tabular-nums}
.exd-parent-child *{box-sizing:border-box}
.exd-parent-child-hd{display:flex;align-items:center;gap:6px;font-size:8px;letter-spacing:.12em;color:var(--exd-pc-dim)}
.exd-parent-child-oid{font-family:var(--exd-pc-mono);color:#95A4BC;font-weight:700}
.exd-parent-child-ord{margin-left:auto;font-family:var(--exd-pc-mono);font-size:9px;color:#C9D4E6;letter-spacing:.02em}
.exd-parent-child-sl{color:var(--exd-pc-dn);font-weight:800;margin-right:5px}
.exd-parent-child-algo{font-family:var(--exd-pc-mono);font-size:8px;padding:1px 4px;border:1px solid rgba(110,168,255,.3);border-radius:3px;color:#9EC4FF}
.exd-parent-child-track{position:relative;height:12px;margin:7px 0 3px;border:1px solid var(--exd-pc-ln);border-radius:3px;background:rgba(255,255,255,.03);overflow:hidden}
.exd-parent-child-fill{height:100%;width:65.1%;background:linear-gradient(90deg,rgba(53,208,127,.55),rgba(53,208,127,.28));border-right:1px solid rgba(53,208,127,.85);transition:width .5s ease}
.exd-parent-child-tick{position:absolute;top:0;bottom:0;left:68.2%;width:1px;background:var(--exd-pc-wn);transition:left .5s ease}
.exd-parent-child-tickl{position:absolute;top:1px;left:3px;font-family:var(--exd-pc-mono);font-size:6.5px;letter-spacing:.1em;color:var(--exd-pc-wn);white-space:nowrap}
.exd-parent-child-brow{display:flex;justify-content:space-between;font-family:var(--exd-pc-mono);font-size:8px;letter-spacing:.06em;color:var(--exd-pc-dim);padding-bottom:6px;border-bottom:1px solid var(--exd-pc-ln)}
.exd-parent-child-pct{color:#DCE4F2}
.exd-parent-child-sch{color:var(--exd-pc-wn)}
.exd-parent-child-ok{color:var(--exd-pc-up)}
.exd-parent-child-kpi{display:grid;grid-template-columns:repeat(3,1fr);gap:4px 6px;padding:6px 0;border-bottom:1px solid var(--exd-pc-ln)}
.exd-parent-child-k{display:flex;flex-direction:column;gap:1px;min-width:0}
.exd-parent-child-k span{font-size:7px;letter-spacing:.1em;color:var(--exd-pc-dim);white-space:nowrap}
.exd-parent-child-k b{font-family:var(--exd-pc-mono);font-size:10.5px;font-weight:600;color:#F2F6FF}
.exd-parent-child-arr,.exd-parent-child-vw{color:var(--exd-pc-up)}
.exd-parent-child-neg{color:var(--exd-pc-dn)}
.exd-parent-child-lhd{display:grid;grid-template-columns:48px 36px 1fr 54px;gap:4px;font-size:7px;letter-spacing:.12em;color:#4E5A70;padding:5px 2px 3px}
.exd-parent-child-r{text-align:right}
.exd-parent-child-log{max-height:78px;overflow-y:auto;overscroll-behavior:contain}
.exd-parent-child-row{display:grid;grid-template-columns:48px 36px 1fr 54px;gap:4px;padding:2px;font-family:var(--exd-pc-mono);font-size:9px;color:#AEBBD1;border-bottom:1px solid rgba(25,33,47,.65)}
.exd-parent-child-row b{color:#E6EBF5;font-weight:600;text-align:right}
.exd-parent-child-q{text-align:right;color:#C9D4E6}
.exd-parent-child-dk{color:#B78CFF}
.exd-parent-child-new{animation:exd-parent-child-flash 900ms ease-out}
.exd-parent-child-ft{display:flex;align-items:center;gap:5px;padding-top:5px;font-size:7.5px;letter-spacing:.11em;color:#4E5A70}
.exd-parent-child-pip{width:5px;height:5px;border-radius:50%;background:var(--exd-pc-up);animation:exd-parent-child-blink 1.8s ease-in-out infinite}
.exd-parent-child-st{color:var(--exd-pc-up);font-weight:700}
.exd-parent-child-cnt{margin-left:auto;font-family:var(--exd-pc-mono)}
@keyframes exd-parent-child-flash{0%{background:rgba(53,208,127,.28)}100%{background:transparent}}
@keyframes exd-parent-child-blink{0%,100%{opacity:1}50%{opacity:.25}}
.exd-parent-child-log{scrollbar-width:thin;scrollbar-color:#26314A transparent}
.exd-parent-child-log::-webkit-scrollbar{width:4px}
.exd-parent-child-log::-webkit-scrollbar-track{background:transparent}
.exd-parent-child-log::-webkit-scrollbar-thumb{background:#26314A;border-radius:2px}
@media (prefers-reduced-motion: reduce){
.exd-parent-child-pip{animation:none}
.exd-parent-child-new{animation:none}
.exd-parent-child-fill,.exd-parent-child-tick{transition:none}
}

js:
var QTY=480000,ARR=224.18;
var done=312400,notl=done*224.31,mvwap=224.26,sched=68.2,clock=14*3600+26*60+5,fills=184;
var VEN=[['XNAS',0],['ARCX',0],['XNYS',0],['BATS',0],['EDGX',0],['IEXG',0],['UBSA',1],['SGMA',1]];
var CLIP=[500,700,900,1200,1500,1800,2200,2600,3000];
var log=root.querySelector('.exd-parent-child-log');
var fillEl=root.querySelector('.exd-parent-child-fill');
var tickEl=root.querySelector('.exd-parent-child-tick');
var track=root.querySelector('.exd-parent-child-track');
function n0(v){return Math.round(v).toLocaleString('en-US');}
function hms(t){var h=Math.floor(t/3600)%24,m=Math.floor(t/60)%60,s=t%60;return ('0'+h).slice(-2)+':'+('0'+m).slice(-2)+':'+('0'+s).slice(-2);}
function bps(a,b){return (a-b)/b*1e4;}
function sign(v,d){return (v>=0?'+':'−')+Math.abs(v).toFixed(d);}
function paint(){
  var avg=notl/done,pct=done/QTY*100;
  fillEl.style.width=pct.toFixed(2)+'%';
  tickEl.style.left=Math.min(100,sched).toFixed(2)+'%';
  track.setAttribute('aria-valuenow',Math.round(pct));
  root.querySelector('.exd-parent-child-pct').textContent=pct.toFixed(1)+'% FILLED';
  var gap=pct-sched,sc=root.querySelector('.exd-parent-child-sch');
  sc.textContent='SCHED '+Math.min(100,sched).toFixed(1)+'% · '+(gap>=0?'AHEAD ':'BEHIND ')+Math.abs(gap).toFixed(1)+'pp';
  sc.classList.toggle('exd-parent-child-ok',gap>=0);
  root.querySelector('.exd-parent-child-done').textContent=n0(done);
  root.querySelector('.exd-parent-child-left').textContent=n0(QTY-done);
  root.querySelector('.exd-parent-child-avg').textContent=avg.toFixed(4);
  var a=bps(avg,ARR),v=bps(avg,mvwap);
  var ae=root.querySelector('.exd-parent-child-arr'),ve=root.querySelector('.exd-parent-child-vw');
  ae.textContent=sign(a,1)+' bp';ve.textContent=sign(v,1)+' bp';
  ae.classList.toggle('exd-parent-child-neg',a<0);
  ve.classList.toggle('exd-parent-child-neg',v<0);
  root.querySelector('.exd-parent-child-prt').textContent=(12*pct/sched).toFixed(1)+'%';
  root.querySelector('.exd-parent-child-cnt').textContent=fills+' child fills';
}
function add(){
  var q=Math.min(QTY-done,CLIP[Math.floor(Math.random()*CLIP.length)]);
  if(q<=0)return false;
  var px=Math.round((224.30+(Math.random()-0.48)*0.09)*100)/100;
  var v=VEN[Math.floor(Math.random()*VEN.length)];
  done+=q;notl+=q*px;fills++;
  mvwap=mvwap+(px-mvwap)*0.03;
  sched=Math.min(100,sched+0.38);
  clock+=6+Math.floor(Math.random()*14);
  var r=document.createElement('div');
  r.className='exd-parent-child-row exd-parent-child-new';
  r.innerHTML='<span></span><span class="'+(v[1]?'exd-parent-child-dk':'')+'"></span><span class="exd-parent-child-q"></span><b></b>';
  r.children[0].textContent=hms(clock);
  r.children[1].textContent=v[0];
  r.children[2].textContent=n0(q);
  r.children[3].textContent=px.toFixed(2);
  log.insertBefore(r,log.firstChild);
  while(log.children.length>40)log.removeChild(log.lastChild);
  return true;
}
var seed=[[14*3600+25*60+51,'XNAS',1500,224.29],[14*3600+25*60+38,'UBSA',2600,224.32],[14*3600+25*60+24,'ARCX',900,224.30],[14*3600+25*60+9,'BATS',1200,224.28],[14*3600+24*60+55,'XNAS',700,224.31]];
seed.forEach(function(s){
  var r=document.createElement('div');
  r.className='exd-parent-child-row';
  r.innerHTML='<span></span><span class="'+(s[1]==='UBSA'?'exd-parent-child-dk':'')+'"></span><span class="exd-parent-child-q"></span><b></b>';
  r.children[0].textContent=hms(s[0]);r.children[1].textContent=s[1];
  r.children[2].textContent=n0(s[2]);r.children[3].textContent=s[3].toFixed(2);
  log.appendChild(r);
});
paint();
var iv=window.setInterval(function(){
  if(!root.isConnected){window.clearInterval(iv);return;}
  if(!add()){
    window.clearInterval(iv);
    root.querySelector('.exd-parent-child-st').textContent='COMPLETE';
    return;
  }
  paint();
},1400);

css:
.exd-venue-route{--exd-vr-ln:#19212F;--exd-vr-dim:#6C7A92;--exd-vr-up:#35D07F;--exd-vr-dn:#FF5F6D;--exd-vr-drk:#B78CFF;--exd-vr-mono:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;box-sizing:border-box;width:100%;background:linear-gradient(180deg,#0E131C,#090C12);border:1px solid var(--exd-vr-ln);border-radius:8px;padding:8px 9px 7px;color:#E6EBF5;font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;font-size:10px;font-variant-numeric:tabular-nums}
.exd-venue-route *{box-sizing:border-box}
