.exd-venue-route-cols{display:grid;grid-template-columns:1fr 34px 50px 32px 34px;gap:4px;padding:5px 2px 3px;border-bottom:1px solid var(--exd-vr-ln)}
.exd-venue-route-h{appearance:none;background:none;border:0;padding:0;font:inherit;font-size:7px;letter-spacing:.12em;color:#4E5A70;cursor:pointer;text-align:left}
.exd-venue-route-h:hover{color:#8FA3C0}
.exd-venue-route-h:focus-visible{outline:none;color:#9EC4FF;text-decoration:underline}
.exd-venue-route-r{text-align:right}
