var TOT=500000;
var V=[
 {name:'NASDAQ',mic:'XNAS',sh:142000,fr:61.8,mk:0.42,d:0},
 {name:'ARCA',mic:'ARCX',sh:95500,fr:57.3,mk:0.31,d:0},
 {name:'NYSE',mic:'XNYS',sh:73000,fr:64.1,mk:0.18,d:0},
 {name:'CBOE BZX',mic:'BATS',sh:59000,fr:52.7,mk:0.55,d:0},
 {name:'EDGX',mic:'EDGX',sh:41500,fr:49.2,mk:0.61,d:0},
 {name:'IEX',mic:'IEXG',sh:31000,fr:44.6,mk:-0.12,d:0},
 {name:'UBS ATS',mic:'UBSA',sh:29500,fr:22.4,mk:-0.34,d:1},
 {name:'SIGMA X',mic:'SGMA',sh:17000,fr:18.9,mk:-0.21,d:1},
 {name:'LEVEL ATS',mic:'LEVL',sh:11500,fr:15.6,mk:0.07,d:1}
];
var rows=root.querySelector('.exd-venue-route-rows');
var sum=0,sent=0,dark=0;
V.forEach(function(v){v.pct=v.sh/TOT*100;sum+=v.sh;sent+=v.sh/(v.fr/100);if(v.d)dark+=v.sh;});
var maxp=V[0].pct,key='pct',dir=-1;
function n0(n){return Math.round(n).toLocaleString('en-US');}
function draw(){
  var list=V.slice().sort(function(a,b){
    if(key==='name')return a.name<b.name?dir*-1:dir;
    return (a[key]-b[key])*dir;
  });
  rows.innerHTML='';
  list.forEach(function(v){
    var r=document.createElement('div');
    r.className='exd-venue-route-row'+(v.d?' exd-venue-route-dk':'');
    r.style.setProperty('--exd-vr-w',(v.pct/maxp*100).toFixed(1)+'%');
    r.innerHTML='<span class="exd-venue-route-v"><i class="exd-venue-route-dot'+(v.d?' exd-venue-route-dot-d':'')+'"></i></span>'+
      '<span class="exd-venue-route-p"></span><span class="exd-venue-route-s"></span>'+
      '<span class="exd-venue-route-f"></span><span class="exd-venue-route-m"></span>';
    r.children[0].appendChild(document.createTextNode(v.mic));
    r.children[0].title=v.name;
    r.children[1].textContent=v.pct.toFixed(1);
    r.children[2].textContent=n0(v.sh);
    r.children[3].textContent=v.fr.toFixed(1);
    var m=r.children[4];
    m.textContent=(v.mk>=0?'+':'−')+Math.abs(v.mk).toFixed(2);
    m.className='exd-venue-route-m '+(v.mk>=0?'exd-venue-route-pos':'exd-venue-route-neg');
    rows.appendChild(r);
  });
}
Array.prototype.forEach.call(root.querySelectorAll('.exd-venue-route-h'),function(b){
  b.addEventListener('click',function(){
    var k=b.getAttribute('data-k');
    dir=(k===key)?-dir:(k==='name'?1:-1);
    key=k;
    Array.prototype.forEach.call(root.querySelectorAll('.exd-venue-route-h'),function(x){
      x.classList.toggle('exd-venue-route-on',x===b);
    });
    draw();
  });
});
var litPct=(sum-dark)/sum*100;
root.querySelector('.exd-venue-route-lit').style.width=litPct.toFixed(1)+'%';
root.querySelector('.exd-venue-route-drk').style.width=(100-litPct).toFixed(1)+'%';
root.querySelector('.exd-venue-route-f1').textContent='LIT '+litPct.toFixed(1)+'%';
root.querySelector('.exd-venue-route-f2').textContent='DARK '+(100-litPct).toFixed(1)+'%';
root.querySelector('.exd-venue-route-f3').textContent='BLENDED FR '+(sum/sent*100).toFixed(1)+'%';
root.querySelector('.exd-venue-route-ord').textContent='PA-8841 · '+(sum/1000)+'k AAPL';
draw();

