var QTY=180000,AVG=121.5540;
var B=[['ARRIVAL',121.4820],['INT VWAP',121.5710],['TWAP',121.5980],['OPEN',121.3300],['PREV CLS',120.9100]];
var NOTL=QTY*AVG,MIN=-10,MAX=30;
var wrap=root.querySelector('.exd-tca-card-bm');
var mark=root.querySelector('.exd-tca-card-mark');
var cur=0;
function bps(b){return (AVG-b)/b*1e4;}
function usd(n){var a=Math.abs(Math.round(n));return (n<0?'−$':'$')+a.toLocaleString('en-US');}
function sel(i){
  cur=i;
  var v=bps(B[i][1]);
  var ve=root.querySelector('.exd-tca-card-v');
  ve.textContent=(v>=0?'+':'−')+Math.abs(v).toFixed(2);
  ve.className='exd-tca-card-v '+(v>=0?'exd-tca-card-bad':'exd-tca-card-good');
  root.querySelector('.exd-tca-card-lbl').textContent=(v>=0?'COST vs ':'SAVED vs ')+B[i][0];
  root.querySelector('.exd-tca-card-dol').textContent=usd(NOTL*v/1e4)+' · '+(NOTL/1e6).toFixed(1)+'M NTL';
  var p=Math.max(0,Math.min(100,(v-MIN)/(MAX-MIN)*100));
  mark.style.left=p.toFixed(1)+'%';
  mark.style.background=v>=0?'#F3B44A':'#35D07F';
  root.querySelector('.exd-tca-card-rank').textContent=i===0?'38th pctile':'n/a for benchmark';
  Array.prototype.forEach.call(wrap.children,function(c,j){c.classList.toggle('exd-tca-card-sel',j===i);});
}
B.forEach(function(b,i){
  var v=bps(b[1]);
  var r=document.createElement('button');
  r.type='button';
  r.className='exd-tca-card-row';
  r.innerHTML='<span></span><span class="exd-tca-card-bpx"></span><span class="exd-tca-card-bbp"></span>';
  r.children[0].textContent=b[0];
  r.children[1].textContent=b[1].toFixed(4);
  r.children[2].textContent=(v>=0?'+':'−')+Math.abs(v).toFixed(2);
  r.children[2].className='exd-tca-card-bbp '+(v>=0?'exd-tca-card-pos':'exd-tca-card-neg');
  r.addEventListener('click',function(){sel(i);});
  r.addEventListener('keydown',function(e){
    if(e.key==='ArrowDown'){e.preventDefault();wrap.children[Math.min(B.length-1,i+1)].focus();}
    if(e.key==='ArrowUp'){e.preventDefault();wrap.children[Math.max(0,i-1)].focus();}
  });
  wrap.appendChild(r);
});
var D=[1.82,3.41,1.35,-0.65],gross=0;
D.forEach(function(d){gross+=Math.abs(d);});
D.forEach(function(d,i){root.querySelector('.exd-tca-card-s'+(i+1)).style.width=(Math.abs(d)/gross*100).toFixed(1)+'%';});
root.querySelector('.exd-tca-card-ord').innerHTML='<b class="exd-tca-card-by">BUY</b>'+QTY.toLocaleString('en-US')+' NVDA';
sel(0);

