  r.children[1].lastChild.textContent=o.sym;
  r.children[2].textContent=o.ty;
  r.children[3].textContent=n0(o.q);
  r.children[4].textContent=o.s==='PART'?(o.s+' '+Math.round(o.d/o.q*100)):o.s;
