];
B.forEach(function(b){b.on=true;b.notl=b.sh*b.px;b.bp=2.1+6.4*Math.sqrt(b.adv);});
var rows=root.querySelector('.exd-basket-grid-rows');
var send=root.querySelector('.exd-basket-grid-send');
var key='notl',dir=-1;
function m(n){return '$'+(n/1e6).toFixed(2)+'M';}
function tot(){
  var buy=0,sell=0,wc=0,n=0;
  B.forEach(function(b){
    if(!b.on)return;
    n++;
    if(b.sd>0)buy+=b.notl;else sell+=b.notl;
    wc+=b.notl*b.bp;
  });
  var gross=buy+sell,net=buy-sell;
  root.querySelector('.exd-basket-grid-tb').textContent=m(buy);
  root.querySelector('.exd-basket-grid-ts').textContent=m(sell);
  root.querySelector('.exd-basket-grid-tg').textContent=m(gross);
  var ne=root.querySelector('.exd-basket-grid-tn');
  ne.textContent=(net>=0?'+':'−')+m(Math.abs(net));
  ne.style.color=net>=0?'#35D07F':'#FF5F6D';
  root.querySelector('.exd-basket-grid-cnt').textContent=n+'/'+B.length;
  root.querySelector('.exd-basket-grid-bbuy').style.width=(gross?buy/gross*100:0).toFixed(1)+'%';
  root.querySelector('.exd-basket-grid-bsel').style.width=(gross?sell/gross*100:0).toFixed(1)+'%';
  send.textContent=n?('STAGE '+n+' NAMES · EST '+(wc/gross).toFixed(1)+' bps'):'NO NAMES SELECTED';
  send.disabled=!n;
}
function draw(){
  var list=B.slice().sort(function(a,b){
    if(key==='sym')return a.sym<b.sym?-dir:dir;
