    var b=bps(r);
    d.innerHTML='<span class="exd-axe-ioi-bkr"><i class="exd-axe-ioi-sd"></i><span></span></span>'+
      '<span class="exd-axe-ioi-sym"></span>'+
      '<span class="exd-axe-ioi-sz"></span><span class="exd-axe-ioi-lv"></span>'+
      '<span class="exd-axe-ioi-bp"></span><span class="exd-axe-ioi-tt"></span>';
    var sd=d.children[0].firstChild;
    sd.className='exd-axe-ioi-sd '+(r.sd>0?'exd-axe-ioi-b':'exd-axe-ioi-s');
    sd.textContent=r.sd>0?'B':'S';
    d.children[0].lastChild.textContent=r.bkr;
    d.children[1].textContent=r.sym;
    d.children[2].innerHTML='<span class="exd-axe-ioi-q"></span>';
    d.children[2].insertBefore(document.createTextNode(k(r.sz)),d.children[2].firstChild);
    d.children[2].lastChild.textContent=' '+r.q;
    d.children[3].textContent=r.lv.toFixed(2);
    d.children[4].textContent=(b>=0?'+':'−')+Math.abs(b).toFixed(1);
    d.children[5].textContent=r.ttl<=0?'EXP':mmss(r.ttl);
    if(r.ttl>0&&r.ttl<60)d.children[5].className='exd-axe-ioi-tt exd-axe-ioi-warn';
    d.title=r.bkr+' '+(r.sd>0?'bid':'offer')+' '+r.sym+' — '+(r.q==='N'?'natural':(r.q==='S'?'super-natural':'potential'));
    r.el=d;
    rows.appendChild(d);
  });
  root.querySelector('.exd-axe-ioi-sum').textContent='IND $'+(notl/1e6).toFixed(1)+'M';
  root.querySelector('.exd-axe-ioi-n').textContent=n;
}
Array.prototype.forEach.call(root.querySelectorAll('.exd-axe-ioi-f'),function(b){
  b.addEventListener('click',function(){
    filt=b.getAttribute('data-f');
    Array.prototype.forEach.call(root.querySelectorAll('.exd-axe-ioi-f'),function(x){
      x.classList.toggle('exd-axe-ioi-on',x===b);
    });
    draw();
  });
});
draw();
var iv=window.setInterval(function(){
  if(!root.isConnected){window.clearInterval(iv);return;}
  var swap=false;
  for(var i=L.length-1;i>=0;i--){
    var r=L[i];
    if(r.ttl>-3)r.ttl--;
    if(r.ttl===-3){
      var p=POOL[pi%POOL.length];pi++;
      L.splice(i,1,{bkr:p.bkr,sd:p.sd,sym:p.sym,sz:p.sz,lv:p.lv,mid:p.mid,q:p.q,ttl:p.ttl,fresh:true});
      swap=true;
    }
  }
  if(swap){draw();return;}
  L.forEach(function(r){
    if(!r.el)return;
    var c=r.el.children[5];
    c.textContent=r.ttl<=0?'EXP':mmss(r.ttl);
    c.className='exd-axe-ioi-tt'+(r.ttl>0&&r.ttl<60?' exd-axe-ioi-warn':'');
    r.el.classList.toggle('exd-axe-ioi-dead',r.ttl<=0);
  });
},1000);

