js:
var Q=420000,PX=112.44,ADV=17500000,SESS=390,SIG=162,HS=1.1,LAM=0.20;
var NOTL=Q*PX;
var H=[{m:15,l:'15m'},{m:30,l:'30m'},{m:60,l:'1h'},{m:120,l:'2h'},{m:240,l:'4h'},{m:390,l:'EOD'}];
H.forEach(function(h){
  var pov=Q/(ADV*h.m/SESS);
  h.pov=pov;
  h.imp=0.10*SIG*Math.pow(pov,0.6);
  h.spr=HS*(0.35+0.65*Math.min(1,pov*1.6));
  h.cost=h.imp+h.spr;
  h.risk=SIG*Math.sqrt(h.m/SESS)/Math.sqrt(3);
  h.u=h.cost+LAM*h.risk;
});
var opt=0;
H.forEach(function(h,i){if(h.u<H[opt].u)opt=i;});
var cur=opt;
var chips=root.querySelector('.exd-pretrade-cost-hz');
var plot=root.querySelector('.exd-pretrade-cost-plot');
var X0=24,X1=244,Y0=8,Y1=54,RMAX=100,CMAX=14;
function px(r){return X0+Math.min(1,r/RMAX)*(X1-X0);}
function py(c){return Y1-Math.min(1,c/CMAX)*(Y1-Y0);}
function chart(){
  var d='',s='';
  H.forEach(function(h,i){d+=(i?'L':'M')+px(h.risk).toFixed(1)+' '+py(h.cost).toFixed(1);});
  s+='<line class="exd-pretrade-cost-ax" x1="'+X0+'" y1="'+Y1+'" x2="'+X1+'" y2="'+Y1+'"></line>';
  s+='<line class="exd-pretrade-cost-ax" x1="'+X0+'" y1="'+Y0+'" x2="'+X0+'" y2="'+Y1+'"></line>';
  s+='<path class="exd-pretrade-cost-cv" d="'+d+'"></path>';
  H.forEach(function(h,i){
    var c='exd-pretrade-cost-pt'+(i===opt?' exd-pretrade-cost-optpt':'')+(i===cur?' exd-pretrade-cost-cur':'');
    s+='<circle class="'+c+'" cx="'+px(h.risk).toFixed(1)+'" cy="'+py(h.cost).toFixed(1)+'" r="'+(i===cur?3:2.2)+'"></circle>';
  });
  s+='<text class="exd-pretrade-cost-lb" x="'+X0+'" y="66">RISK 1σ bps →</text>';
  s+='<text class="exd-pretrade-cost-lb" x="'+X1+'" y="66" text-anchor="end">'+RMAX+'</text>';
  s+='<text class="exd-pretrade-cost-lb" x="2" y="12">'+CMAX+' bps</text>';
  s+='<text class="exd-pretrade-cost-lb" x="2" y="'+(Y1+2)+'">COST</text>';
  plot.innerHTML=s;
}
function paint(){
  var h=H[cur];
  root.querySelector('.exd-pretrade-cost-pov').textContent=(h.pov*100).toFixed(1)+'%';
  root.querySelector('.exd-pretrade-cost-exp').textContent=(Math.round(h.spr*100)/100+Math.round(h.imp*100)/100).toFixed(2);
  root.querySelector('.exd-pretrade-cost-rsk').textContent='±'+h.risk.toFixed(1);
  root.querySelector('.exd-pretrade-cost-usd').textContent='$'+(NOTL*h.cost/1e4/1000).toFixed(1)+'k';
  var sp2=Math.round(h.spr*100)/100,im2=Math.round(h.imp*100)/100,tt2=sp2+im2;
  root.querySelector('.exd-pretrade-cost-sp').textContent='+'+sp2.toFixed(2);
  root.querySelector('.exd-pretrade-cost-im').textContent='+'+im2.toFixed(2);
  root.querySelector('.exd-pretrade-cost-tt').textContent='+'+tt2.toFixed(2)+' bps';
  var lo=h.cost-1.96*h.risk,hi=h.cost+1.96*h.risk;
  root.querySelector('.exd-pretrade-cost-bd').textContent=(lo>=0?'+':'−')+Math.abs(lo).toFixed(1)+' / +'+hi.toFixed(1);
  root.querySelector('.exd-pretrade-cost-wrn').textContent=h.pov>0.25?'POV > 25% CAP · EXTRAPOLATED':(cur===opt?'MIN COST+RISK':'');
  Array.prototype.forEach.call(chips.children,function(c,i){c.classList.toggle('exd-pretrade-cost-on',i===cur);});
  chart();
}
H.forEach(function(h,i){
  var b=document.createElement('button');
  b.type='button';
  b.className='exd-pretrade-cost-c'+(i===opt?' exd-pretrade-cost-opt':'');
  b.textContent=h.l;
  b.setAttribute('aria-label',h.l+' horizon, expected cost '+h.cost.toFixed(2)+' bps');
  b.addEventListener('click',function(){cur=i;paint();});
  b.addEventListener('keydown',function(e){
    if(e.key==='ArrowRight'){e.preventDefault();cur=Math.min(H.length-1,cur+1);chips.children[cur].focus();paint();}
    if(e.key==='ArrowLeft'){e.preventDefault();cur=Math.max(0,cur-1);chips.children[cur].focus();paint();}
  });
  chips.appendChild(b);
});
paint();
